export const LOCOMOTION_MOVEMENT = [
  // ---- MCQ ----
  { id: 'lm-1', type: 'mcq', question: 'Movement shown by white blood cells (leucocytes) using pseudopodia is an example of:', options: ['Ciliary movement', 'Amoeboid movement', 'Muscular movement', 'Flagellar movement'], correctIndex: 1, explanation: 'Leucocytes move using pseudopodia formed by cytoskeletal elements — amoeboid movement.', difficulty: 'easy' },
  { id: 'lm-2', type: 'mcq', question: 'Movement of ova through the female reproductive tract is facilitated mainly by:', options: ['Amoeboid movement', 'Ciliary movement', 'Muscular movement', 'Flagellar movement'], correctIndex: 1, explanation: 'Ciliary movement, seen in the lining of the fallopian tube, helps move the ovum toward the uterus.', difficulty: 'medium' },
  { id: 'lm-3', type: 'mcq', question: 'Locomotion in the human body is primarily achieved through:', options: ['Amoeboid movement only', 'Muscular movement, involving contraction of skeletal muscles', 'Ciliary movement only', 'Passive diffusion'], correctIndex: 1, explanation: 'Human locomotion is driven mainly by muscular movement, particularly skeletal muscle contraction.', difficulty: 'easy' },
  { id: 'lm-4', type: 'mcq', question: 'The total number of bones present in the adult human skeletal system is approximately:', options: ['186', '206', '226', '246'], correctIndex: 1, explanation: 'The adult human skeleton comprises 206 bones.', difficulty: 'easy' },
  { id: 'lm-5', type: 'mcq', question: 'The axial skeleton in humans includes bones of the:', options: ['Limbs only', 'Skull, vertebral column, ribs, and sternum', 'Pelvic girdle only', 'Pectoral girdle only'], correctIndex: 1, explanation: 'The axial skeleton comprises the skull, vertebral column, ribs, and sternum — 80 bones total.', difficulty: 'medium' },
  { id: 'lm-6', type: 'mcq', question: 'The appendicular skeleton in humans includes:', options: ['Skull bones only', 'The bones of the limbs, along with the pectoral and pelvic girdles', 'Vertebral column only', 'Ribs and sternum only'], correctIndex: 1, explanation: 'The appendicular skeleton comprises limb bones plus the pectoral and pelvic girdles — 126 bones total.', difficulty: 'medium' },
  { id: 'lm-7', type: 'mcq', question: 'The human skull is composed of how many bones (cranial and facial together)?', options: ['8', '14', '22', '29'], correctIndex: 2, explanation: 'The skull consists of 22 bones — 8 cranial and 14 facial bones.', difficulty: 'medium' },
  { id: 'lm-8', type: 'mcq', question: 'The human vertebral column typically consists of how many vertebrae?', options: ['26', '24', '33', '20'], correctIndex: 0, explanation: 'The vertebral column consists of 26 vertebrae in adults (after fusion of sacral and coccygeal segments).', difficulty: 'medium' },
  { id: 'lm-9', type: 'mcq', question: 'The human rib cage is formed by how many pairs of ribs?', options: ['10 pairs', '11 pairs', '12 pairs', '13 pairs'], correctIndex: 2, explanation: 'There are 12 pairs of ribs forming the rib cage.', difficulty: 'medium' },
  { id: 'lm-10', type: 'mcq', question: 'Ribs that are NOT directly or indirectly attached to the sternum are called:', options: ['True ribs', 'False ribs', 'Floating ribs', 'Vertebrosternal ribs'], correctIndex: 2, explanation: 'The last two pairs of ribs, unattached to the sternum, are called floating ribs.', difficulty: 'medium' },
  { id: 'lm-11', type: 'mcq', question: 'The pectoral girdle, connecting the upper limbs to the axial skeleton, consists of:', options: ['Only the clavicle', 'Clavicle and scapula on each side', 'Only the scapula', 'Ilium, ischium, and pubis'], correctIndex: 1, explanation: 'Each half of the pectoral girdle is formed by a clavicle and a scapula.', difficulty: 'medium' },
  { id: 'lm-12', type: 'mcq', question: 'The pelvic girdle, connecting the lower limbs to the axial skeleton, is formed by fusion of:', options: ['Clavicle and scapula', 'Ilium, ischium, and pubis (forming the coxal bone)', 'Femur and tibia', 'Radius and ulna'], correctIndex: 1, explanation: 'The pelvic girdle consists of two coxal (hip) bones, each formed by fusion of the ilium, ischium, and pubis.', difficulty: 'medium' },
  { id: 'lm-13', type: 'mcq', question: 'A joint that permits little to no movement, such as the sutures of the skull, is called a:', options: ['Synovial joint', 'Fibrous joint', 'Cartilaginous joint', 'Ball and socket joint'], correctIndex: 1, explanation: 'Fibrous joints, like skull sutures, allow little to no movement.', difficulty: 'medium' },
  { id: 'lm-14', type: 'mcq', question: 'A joint permitting slight movement, such as between successive vertebrae, is generally classified as a:', options: ['Fibrous joint', 'Cartilaginous joint', 'Freely movable synovial joint', 'Fixed joint'], correctIndex: 1, explanation: 'Cartilaginous joints allow limited movement, as seen between vertebrae.', difficulty: 'medium' },
  { id: 'lm-15', type: 'mcq', question: 'Joints that allow free movement, such as the shoulder and knee, are called:', options: ['Fibrous joints', 'Cartilaginous joints', 'Synovial joints', 'Suture joints'], correctIndex: 2, explanation: 'Synovial joints, characterised by a fluid-filled cavity, permit free movement.', difficulty: 'easy' },
  { id: 'lm-16', type: 'mcq', question: 'The lubricating fluid found within a synovial joint cavity is called:', options: ['Cerebrospinal fluid', 'Synovial fluid', 'Pleural fluid', 'Peritoneal fluid'], correctIndex: 1, explanation: 'Synovial fluid lubricates and reduces friction within synovial joint cavities.', difficulty: 'easy' },
  { id: 'lm-17', type: 'mcq', question: 'The ball and socket joint, allowing movement in almost all directions, is exemplified by the:', options: ['Elbow joint', 'Knee joint', 'Shoulder joint (between humerus and pectoral girdle)', 'Skull sutures'], correctIndex: 2, explanation: 'The shoulder joint is a classic ball-and-socket joint, allowing extensive multi-directional movement.', difficulty: 'medium' },
  { id: 'lm-18', type: 'mcq', question: 'A hinge joint, allowing movement in only one plane, is exemplified by the:', options: ['Shoulder joint', 'Knee joint', 'Hip joint', 'Wrist joint'], correctIndex: 1, explanation: 'The knee joint is a hinge joint, allowing flexion/extension movement in one plane.', difficulty: 'medium' },
  { id: 'lm-19', type: 'mcq', question: 'Skeletal muscle is also known as:', options: ['Smooth or unstriated muscle', 'Striated or voluntary muscle', 'Cardiac muscle', 'Involuntary muscle'], correctIndex: 1, explanation: 'Skeletal muscle shows visible striations and is under voluntary control.', difficulty: 'easy' },
  { id: 'lm-20', type: 'mcq', question: 'Smooth muscle, found in the walls of internal organs like the alimentary canal, is characterised as:', options: ['Striated and voluntary', 'Unstriated and involuntary', 'Striated and involuntary', 'Unstriated and voluntary'], correctIndex: 1, explanation: 'Smooth muscle lacks striations and is under involuntary control.', difficulty: 'easy' },
  { id: 'lm-21', type: 'mcq', question: 'Cardiac muscle, found exclusively in the heart, is characterised as:', options: ['Unstriated and voluntary', 'Striated and involuntary', 'Unstriated and involuntary', 'Striated and voluntary'], correctIndex: 1, explanation: 'Cardiac muscle shows striations (like skeletal muscle) but is involuntary (like smooth muscle) — a unique combination.', difficulty: 'medium' },
  { id: 'lm-22', type: 'mcq', question: 'The connective tissue sheath (fascia) that covers an entire skeletal muscle is called the:', options: ['Sarcolemma', 'Epimysium', 'Endomysium', 'Perimysium'], correctIndex: 1, explanation: 'Epimysium is the connective tissue covering the whole muscle.', difficulty: 'hard' },
  { id: 'lm-23', type: 'mcq', question: 'The plasma membrane of a skeletal muscle fibre is called the:', options: ['Sarcolemma', 'Sarcoplasm', 'Sarcomere', 'Myofibril'], correctIndex: 0, explanation: 'The sarcolemma is the plasma membrane enclosing a muscle fibre.', difficulty: 'easy' },
  { id: 'lm-24', type: 'mcq', question: 'The cytoplasm of a skeletal muscle fibre is referred to as the:', options: ['Sarcolemma', 'Sarcoplasm', 'Myosin', 'Tropomyosin'], correctIndex: 1, explanation: 'Sarcoplasm is the specialised cytoplasm within a muscle fibre.', difficulty: 'medium' },
  { id: 'lm-25', type: 'mcq', question: 'Each muscle fibre contains numerous thread-like structures called:', options: ['Sarcomeres only', 'Myofibrils', 'Fascicles', 'Tendons'], correctIndex: 1, explanation: 'Myofibrils are the thread-like contractile structures packed within each muscle fibre.', difficulty: 'medium' },
  { id: 'lm-26', type: 'mcq', question: 'The repeating functional unit of contraction within a myofibril, lying between two successive Z-lines, is called the:', options: ['Sarcomere', 'Sarcolemma', 'Sarcoplasmic reticulum', 'Tropomyosin complex'], correctIndex: 0, explanation: 'A sarcomere, bounded by two Z-lines, is the basic contractile unit of a myofibril.', difficulty: 'medium' },
  { id: 'lm-27', type: 'mcq', question: 'The thick filaments within a sarcomere are primarily composed of the protein:', options: ['Actin', 'Myosin', 'Tropomyosin', 'Troponin'], correctIndex: 1, explanation: 'Thick filaments are made of the protein myosin.', difficulty: 'easy' },
  { id: 'lm-28', type: 'mcq', question: 'The thin filaments within a sarcomere are primarily composed of the protein:', options: ['Myosin', 'Actin', 'Collagen', 'Keratin'], correctIndex: 1, explanation: 'Thin filaments are mainly composed of the protein actin.', difficulty: 'easy' },
  { id: 'lm-29', type: 'mcq', question: 'The light band (I-band) of a sarcomere, containing only actin filaments, appears:', options: ['Dark under polarised light (anisotropic)', 'Light under polarised light (isotropic)', 'Completely absent in relaxed muscle', 'Only present during muscle contraction'], correctIndex: 1, explanation: 'The I-band contains only thin (actin) filaments and appears light/isotropic under polarised light.', difficulty: 'medium' },
  { id: 'lm-30', type: 'mcq', question: 'The dark band (A-band) of a sarcomere, containing myosin filaments (with or without overlapping actin), appears:', options: ['Light/isotropic', 'Dark/anisotropic under polarised light', 'Invisible under any condition', 'Only present in cardiac muscle'], correctIndex: 1, explanation: 'The A-band, containing myosin (and overlapping actin), appears dark/anisotropic under polarised light.', difficulty: 'medium' },
  { id: 'lm-31', type: 'mcq', question: 'According to the sliding filament theory, muscle contraction occurs due to:', options: ['Shortening of the actin and myosin filaments themselves', 'Actin filaments sliding over myosin filaments, without either filament changing length', 'Complete breakdown of myosin filaments', 'Lengthening of the sarcomere'], correctIndex: 1, explanation: 'Contraction occurs as actin filaments slide over myosin filaments; the filaments themselves do not shorten.', difficulty: 'medium' },
  { id: 'lm-32', type: 'mcq', question: 'During muscle contraction (sliding filament mechanism), which zone of the sarcomere decreases in width?', options: ['A-band width decreases', 'I-band and H-zone width decrease, while A-band width stays constant', 'Only the Z-line disappears', 'The sarcomere itself elongates'], correctIndex: 1, explanation: 'During contraction, the I-band and H-zone shrink as filaments slide, while A-band length remains constant.', difficulty: 'hard' },
  { id: 'lm-33', type: 'mcq', question: 'The signal for muscle contraction is initiated when a neural signal reaches a muscle fibre through a:', options: ['Sarcomere', 'Neuromuscular junction (motor end plate)', 'Tendon', 'Ligament'], correctIndex: 1, explanation: 'The neuromuscular junction is where a motor neuron transmits its signal to trigger muscle fibre contraction.', difficulty: 'medium' },
  { id: 'lm-34', type: 'mcq', question: 'The neurotransmitter released at the neuromuscular junction to trigger muscle contraction is:', options: ['Dopamine', 'Acetylcholine', 'Serotonin', 'GABA'], correctIndex: 1, explanation: 'Acetylcholine is released at the neuromuscular junction, generating an action potential in the muscle fibre.', difficulty: 'medium' },
  { id: 'lm-35', type: 'mcq', question: 'The release of calcium ions, essential for triggering muscle contraction, occurs from the:', options: ['Mitochondria', 'Sarcoplasmic reticulum', 'Nucleus', 'Golgi apparatus'], correctIndex: 1, explanation: 'Calcium ions are stored in and released from the sarcoplasmic reticulum to initiate contraction.', difficulty: 'medium' },
  { id: 'lm-36', type: 'mcq', question: 'The binding of calcium ions to which protein exposes the myosin-binding sites on actin, allowing contraction to proceed?', options: ['Myosin', 'Troponin', 'Tropomyosin (directly, without troponin involvement)', 'Collagen'], correctIndex: 1, explanation: 'Calcium binds troponin, causing a shift in tropomyosin that exposes actin\'s myosin-binding sites.', difficulty: 'hard' },
  { id: 'lm-37', type: 'mcq', question: "The 'cross bridges' formed during muscle contraction refer to the temporary attachment between:", options: ['Actin and troponin', 'Myosin heads and actin filaments', 'Two adjacent Z-lines', 'Sarcolemma and sarcoplasmic reticulum'], correctIndex: 1, explanation: 'Cross bridges are the temporary myosin head-actin attachments formed during the contraction cycle.', difficulty: 'medium' },
  { id: 'lm-38', type: 'mcq', question: 'ATP is required in skeletal muscle contraction mainly for:', options: ['Only the initial nerve signal transmission', 'Both cross bridge formation/power stroke and detachment (breaking the actin-myosin bond)', 'Only forming new actin filaments', 'No role in contraction, only in relaxation'], correctIndex: 1, explanation: 'ATP powers the myosin head movement (power stroke) and is also needed to detach myosin from actin, allowing the cycle to repeat.', difficulty: 'hard' },
  { id: 'lm-39', type: 'mcq', question: 'Continuous stimulation of a muscle without adequate rest can lead to a condition called:', options: ['Muscle fatigue, due to ATP and oxygen deficiency along with lactic acid accumulation', 'Immediate muscle growth', 'Permanent muscle paralysis in all cases', 'Muscle regeneration'], correctIndex: 0, explanation: 'Muscle fatigue results from depleted ATP/oxygen and lactic acid buildup during prolonged activity.', difficulty: 'medium' },
  { id: 'lm-40', type: 'mcq', question: 'Red muscle fibres, rich in the oxygen-storing pigment myoglobin, are also known as:', options: ['White fibres', 'Fast-twitch fibres only', 'Aerobic (red) fibres', 'Cardiac fibres exclusively'], correctIndex: 2, explanation: 'Red/aerobic fibres are rich in myoglobin, giving them a reddish colour and supporting sustained aerobic activity.', difficulty: 'medium' },
  { id: 'lm-41', type: 'mcq', question: 'White muscle fibres, which primarily rely on anaerobic metabolism, contain relatively:', options: ['High myoglobin content and are highly aerobic', 'Fewer mitochondria and lower myoglobin, relying more on anaerobic glycolysis', 'Only cardiac-type contractile proteins', 'No contractile filaments at all'], correctIndex: 1, explanation: 'White fibres have fewer mitochondria/myoglobin, favouring rapid, anaerobic contraction over sustained aerobic activity.', difficulty: 'medium' },
  { id: 'lm-42', type: 'mcq', question: 'Myasthenia gravis is a disorder of the neuromuscular junction characterised by:', options: ['Excessive muscle growth', 'Fatigue, weakening, and paralysis of skeletal muscles due to an autoimmune reaction', 'Complete absence of any muscle tissue', 'Overproduction of myosin'], correctIndex: 1, explanation: 'Myasthenia gravis is an autoimmune disorder affecting neuromuscular transmission, causing progressive muscle weakness.', difficulty: 'medium' },
  { id: 'lm-43', type: 'mcq', question: 'Muscular dystrophy refers to:', options: ['A bacterial infection of muscle tissue', 'Progressive degeneration of skeletal muscle, usually due to a genetic disorder', 'A type of joint inflammation', 'Excessive calcium deposition in muscle'], correctIndex: 1, explanation: 'Muscular dystrophy is a genetic disorder causing progressive weakening and degeneration of skeletal muscles.', difficulty: 'medium' },
  { id: 'lm-44', type: 'mcq', question: 'Tetany, a condition involving rapid, prolonged spasms of skeletal muscle, is typically caused by:', options: ['Excess calcium in the body fluid', 'Deficiency of calcium in the body fluid', 'Excess sodium intake', 'Vitamin C deficiency'], correctIndex: 1, explanation: 'Tetany results from low calcium levels, causing hyperexcitability and prolonged muscle spasms.', difficulty: 'medium' },
  { id: 'lm-45', type: 'mcq', question: 'Arthritis refers to:', options: ['A disorder of muscle tissue only', 'Inflammation of one or more joints', 'A bone fracture', 'A blood clotting disorder'], correctIndex: 1, explanation: 'Arthritis is inflammation of joints, causing pain and restricted movement.', difficulty: 'easy' },
  { id: 'lm-46', type: 'mcq', question: 'Osteoporosis is a bone disorder characterised by:', options: ['Excess bone mass formation', 'Decreased bone mass and increased fracture risk, often associated with reduced hormone (e.g., oestrogen) levels', 'Complete absence of the skeletal system', 'Excess joint fluid'], correctIndex: 1, explanation: 'Osteoporosis involves decreased bone density/mass, increasing fracture risk, commonly linked to hormonal changes with age.', difficulty: 'medium' },
  { id: 'lm-47', type: 'mcq', question: 'Gout, a joint-related disorder, results from the accumulation of:', options: ['Excess calcium deposits', 'Uric acid crystals in the joints', 'Excess synovial fluid only', 'Excess myoglobin'], correctIndex: 1, explanation: 'Gout is caused by uric acid crystal deposition in joints, leading to inflammation and pain.', difficulty: 'medium' },
  { id: 'lm-48', type: 'mcq', question: 'A joint that allows movement primarily in a rotational manner around a single axis, such as between the atlas and axis vertebrae, is called a:', options: ['Hinge joint', 'Pivot joint', 'Saddle joint', 'Gliding joint'], correctIndex: 1, explanation: 'The pivot joint (as between the atlas and axis) allows rotational movement around one axis.', difficulty: 'medium' },
  { id: 'lm-49', type: 'mcq', question: 'A gliding joint, allowing limited sliding movement, is exemplified by joints between:', options: ['The carpal bones of the wrist', 'The femur and hip socket', 'The humerus and scapula', 'The skull sutures'], correctIndex: 0, explanation: 'Gliding joints, like those between carpal bones, allow limited sliding movement.', difficulty: 'medium' },
  { id: 'lm-50', type: 'mcq', question: 'Which of the following best summarises the overall relationship between the skeletal and muscular systems in locomotion?', options: ['They function completely independently with no interaction', 'Muscles provide the contractile force, while the skeleton provides support and acts as a system of levers for movement', 'Only the skeletal system is involved in movement', 'Only the muscular system is involved, with no role for bones'], correctIndex: 1, explanation: 'Locomotion results from coordinated interaction: muscles generate force, and the skeleton provides structural support and leverage.', difficulty: 'medium' },

  // ---- Assertion-Reason ----
  { id: 'lm-ar-1', type: 'assertion-reason', question: 'Assertion (A): Cardiac muscle shows striations similar to skeletal muscle.\nReason (R): Cardiac muscle is under voluntary control, just like skeletal muscle.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 2, explanation: 'A is true (cardiac muscle IS striated), but R is false — cardiac muscle is actually involuntary, unlike skeletal muscle.', difficulty: 'medium' },
  { id: 'lm-ar-2', type: 'assertion-reason', question: 'Assertion (A): The sliding filament theory explains muscle contraction.\nReason (R): During contraction, actin filaments slide over myosin filaments without either filament changing its own length.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This exact filament-sliding mechanism, without filament shortening, is precisely what the sliding filament theory describes.', difficulty: 'medium' },
  { id: 'lm-ar-3', type: 'assertion-reason', question: 'Assertion (A): During muscle contraction, the A-band of the sarcomere shortens significantly.\nReason (R): During contraction, it is the I-band and H-zone that shorten, while the A-band length remains unchanged.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'The A-band does NOT shorten during contraction (A is false); R correctly identifies which bands actually shorten.', difficulty: 'medium' },
  { id: 'lm-ar-4', type: 'assertion-reason', question: 'Assertion (A): Calcium ions play a crucial role in triggering muscle contraction.\nReason (R): Calcium ions bind to troponin, causing a shift in tropomyosin that exposes the myosin-binding sites on actin.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This troponin-tropomyosin mechanism is exactly how calcium ions enable contraction to begin.', difficulty: 'medium' },
  { id: 'lm-ar-5', type: 'assertion-reason', question: 'Assertion (A): ATP is required only for muscle relaxation, not for contraction.\nReason (R): ATP powers both the myosin head power stroke during contraction and the detachment of myosin from actin.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'ATP is actually required for BOTH contraction and detachment/relaxation, not relaxation alone (A is false); R correctly describes its dual role.', difficulty: 'medium' },
  { id: 'lm-ar-6', type: 'assertion-reason', question: 'Assertion (A): Muscle fatigue can occur after prolonged, continuous muscle stimulation.\nReason (R): Prolonged activity depletes ATP and oxygen while allowing lactic acid to accumulate in the muscle.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'ATP/oxygen depletion and lactic acid buildup is exactly the mechanism underlying muscle fatigue.', difficulty: 'medium' },
  { id: 'lm-ar-7', type: 'assertion-reason', question: 'Assertion (A): Red muscle fibres are well-suited for sustained, aerobic activity.\nReason (R): Red fibres are rich in myoglobin and mitochondria, supporting continuous oxidative ATP production.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'High myoglobin/mitochondria content directly supports the sustained aerobic capacity of red fibres.', difficulty: 'medium' },
  { id: 'lm-ar-8', type: 'assertion-reason', question: 'Assertion (A): Myasthenia gravis is a bone disorder caused by calcium deficiency.\nReason (R): Myasthenia gravis is an autoimmune disorder affecting transmission at the neuromuscular junction.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Myasthenia gravis is a neuromuscular junction disorder, not a bone/calcium-deficiency disorder (A is false); R correctly describes its actual autoimmune nature.', difficulty: 'medium' },
  { id: 'lm-ar-9', type: 'assertion-reason', question: 'Assertion (A): Tetany results from excess calcium in the body fluids.\nReason (R): Low calcium levels increase neuromuscular excitability, causing prolonged muscle spasms.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Tetany is actually caused by calcium DEFICIENCY, not excess (A is false); R correctly explains the real mechanism behind it.', difficulty: 'medium' },
  { id: 'lm-ar-10', type: 'assertion-reason', question: 'Assertion (A): Osteoporosis increases the risk of bone fractures.\nReason (R): Osteoporosis involves a decrease in bone mass, often linked to declining hormone levels such as oestrogen.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Reduced bone mass/density directly explains why osteoporosis raises fracture risk.', difficulty: 'medium' },
  { id: 'lm-ar-11', type: 'assertion-reason', question: 'Assertion (A): Gout is a disorder caused by deposition of calcium crystals in joints.\nReason (R): Gout results from accumulation of uric acid crystals in the joints.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Gout is actually caused by uric acid crystals, not calcium crystals (A is false); R correctly identifies the real cause.', difficulty: 'medium' },
  { id: 'lm-ar-12', type: 'assertion-reason', question: 'Assertion (A): The shoulder joint allows a wider range of motion than the knee joint.\nReason (R): The shoulder is a ball-and-socket joint, while the knee is a hinge joint restricted largely to one plane of movement.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This structural difference in joint type is exactly why the shoulder allows much more varied movement than the knee.', difficulty: 'medium' },
  { id: 'lm-ar-13', type: 'assertion-reason', question: 'Assertion (A): Fibrous joints, like skull sutures, allow extensive movement.\nReason (R): Fibrous joints are held together by dense connective tissue, which permits little to no movement.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Fibrous joints actually allow very LITTLE movement, not extensive movement (A is false); R correctly explains why.', difficulty: 'medium' },
  { id: 'lm-ar-14', type: 'assertion-reason', question: 'Assertion (A): The axial skeleton includes the bones of the limbs.\nReason (R): The axial skeleton consists of the skull, vertebral column, ribs, and sternum.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Limb bones actually belong to the APPENDICULAR (not axial) skeleton (A is false); R correctly lists the true components of the axial skeleton.', difficulty: 'medium' },
  { id: 'lm-ar-15', type: 'assertion-reason', question: 'Assertion (A): Skeletal muscle contraction is entirely involuntary.\nReason (R): Skeletal muscle is under conscious, voluntary neural control.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Skeletal muscle is actually VOLUNTARY, not involuntary (A is false); R correctly describes its true voluntary control.', difficulty: 'medium' },
  { id: 'lm-ar-16', type: 'assertion-reason', question: 'Assertion (A): The neuromuscular junction is the site where a motor neuron transmits its signal to a muscle fibre.\nReason (R): Acetylcholine, released at the neuromuscular junction, initiates an action potential in the muscle fibre.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Acetylcholine release triggering the muscle fibre action potential is precisely what happens at the neuromuscular junction.', difficulty: 'medium' },
  { id: 'lm-ar-17', type: 'assertion-reason', question: 'Assertion (A): Sarcoplasmic reticulum is the site of calcium ion storage in muscle fibres.\nReason (R): Calcium release from the sarcoplasmic reticulum is essential for initiating the contraction cycle.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 1, explanation: 'Both statements are true, but R describes a downstream consequence/role rather than directly explaining WHY the SR is the storage site — they are related but separate facts.', difficulty: 'hard' },
  { id: 'lm-ar-18', type: 'assertion-reason', question: 'Assertion (A): Human locomotion depends solely on the skeletal system, with no contribution from muscles.\nReason (R): Muscles provide the contractile force, while the skeleton offers structural support and leverage for movement.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Locomotion depends on BOTH the muscular and skeletal systems working together, not the skeleton alone (A is false); R correctly describes their complementary roles.', difficulty: 'medium' },
  { id: 'lm-ar-19', type: 'assertion-reason', question: 'Assertion (A): White muscle fibres are better suited than red fibres for quick, powerful, but brief bursts of activity.\nReason (R): White fibres rely more on anaerobic glycolysis and fatigue more quickly than red fibres.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Reliance on rapid anaerobic energy release, despite faster fatigue, is exactly why white fibres suit brief, powerful bursts.', difficulty: 'medium' },
  { id: 'lm-ar-20', type: 'assertion-reason', question: 'Assertion (A): The pelvic girdle connects the upper limbs to the axial skeleton.\nReason (R): The pelvic girdle is formed by the fusion of the ilium, ischium, and pubis.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'The pelvic girdle actually connects the LOWER limbs (not upper limbs) to the axial skeleton (A is false); R correctly describes its bony composition.', difficulty: 'medium' },

  // ---- Statement-based ----
  { id: 'lm-st-1', type: 'statement', question: 'Statement I: Amoeboid movement is used by leucocytes.\nStatement II: Ciliary movement helps move the ovum through the fallopian tube.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe these movement types and their examples.', difficulty: 'easy' },
  { id: 'lm-st-2', type: 'statement', question: 'Statement I: The axial skeleton has 80 bones.\nStatement II: The appendicular skeleton has 126 bones.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both figures (80 axial + 126 appendicular = 206 total) are correct.', difficulty: 'medium' },
  { id: 'lm-st-3', type: 'statement', question: 'Statement I: Fibrous joints allow free movement in all directions.\nStatement II: Synovial joints allow free movement.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — fibrous joints allow little to no movement; Statement II correctly describes synovial joints.', difficulty: 'medium' },
  { id: 'lm-st-4', type: 'statement', question: 'Statement I: Skeletal muscle is striated and voluntary.\nStatement II: Smooth muscle is striated and involuntary.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — smooth muscle is UNSTRIATED (not striated), though it is involuntary.', difficulty: 'medium' },
  { id: 'lm-st-5', type: 'statement', question: 'Statement I: Cardiac muscle is striated.\nStatement II: Cardiac muscle is voluntary.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — cardiac muscle is involuntary, not voluntary.', difficulty: 'medium' },
  { id: 'lm-st-6', type: 'statement', question: 'Statement I: The thick filaments of a sarcomere are composed of myosin.\nStatement II: The thin filaments of a sarcomere are composed of actin.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly identify the protein composition of thick and thin filaments.', difficulty: 'easy' },
  { id: 'lm-st-7', type: 'statement', question: 'Statement I: The I-band of a sarcomere contains only myosin filaments.\nStatement II: The A-band of a sarcomere appears dark under polarised light.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — the I-band contains only actin (thin) filaments, not myosin; Statement II correctly describes the A-band.', difficulty: 'medium' },
  { id: 'lm-st-8', type: 'statement', question: 'Statement I: During muscle contraction, the I-band and H-zone shorten.\nStatement II: During muscle contraction, the A-band length remains constant.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the changes (and lack thereof) in sarcomere bands during contraction.', difficulty: 'medium' },
  { id: 'lm-st-9', type: 'statement', question: 'Statement I: Calcium ions bind to tropomyosin directly to trigger contraction.\nStatement II: Calcium ions bind to troponin, which then shifts tropomyosin to expose actin\'s myosin-binding sites.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — calcium binds troponin, not tropomyosin directly; Statement II correctly describes the actual mechanism.', difficulty: 'medium' },
  { id: 'lm-st-10', type: 'statement', question: 'Statement I: ATP is required for the myosin head power stroke.\nStatement II: ATP is also required for detaching the myosin head from actin.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the dual roles ATP plays in the contraction cycle.', difficulty: 'medium' },
  { id: 'lm-st-11', type: 'statement', question: 'Statement I: Red muscle fibres are rich in myoglobin.\nStatement II: White muscle fibres rely mainly on aerobic respiration for energy.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — white fibres rely mainly on ANAEROBIC (not aerobic) metabolism.', difficulty: 'medium' },
  { id: 'lm-st-12', type: 'statement', question: 'Statement I: Myasthenia gravis affects transmission at the neuromuscular junction.\nStatement II: Myasthenia gravis is caused by a bacterial infection.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — myasthenia gravis is an autoimmune disorder, not a bacterial infection.', difficulty: 'medium' },
  { id: 'lm-st-13', type: 'statement', question: 'Statement I: Tetany is caused by calcium deficiency.\nStatement II: Osteoporosis is associated with decreased bone mass.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe these two distinct disorders.', difficulty: 'medium' },
  { id: 'lm-st-14', type: 'statement', question: 'Statement I: Gout results from calcium crystal deposition in joints.\nStatement II: Arthritis refers specifically to inflammation of muscle tissue.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 1, explanation: 'Both statements are incorrect — gout involves uric acid (not calcium) crystals, and arthritis refers to inflammation of joints, not muscle tissue.', difficulty: 'medium' },
  { id: 'lm-st-15', type: 'statement', question: 'Statement I: The shoulder joint is a ball-and-socket joint.\nStatement II: The knee joint is also a ball-and-socket joint.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — the knee is a hinge joint, not a ball-and-socket joint.', difficulty: 'medium' },
  { id: 'lm-st-16', type: 'statement', question: 'Statement I: The pivot joint between the atlas and axis vertebrae allows rotational movement.\nStatement II: Gliding joints, as between carpal bones, allow limited sliding movement.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe these specific joint types and their movement.', difficulty: 'medium' },
  { id: 'lm-st-17', type: 'statement', question: 'Statement I: A myofibril is a single long muscle cell containing many muscle fibres.\nStatement II: A muscle fibre contains many myofibrils.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I has the relationship reversed — a muscle FIBRE is the cell, containing many myofibrils, as correctly described in Statement II.', difficulty: 'medium' },
  { id: 'lm-st-18', type: 'statement', question: 'Statement I: The sarcolemma is the plasma membrane of a muscle fibre.\nStatement II: The sarcoplasm is the specialised cytoplasm of a muscle fibre.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly define these muscle fibre components.', difficulty: 'easy' },
  { id: 'lm-st-19', type: 'statement', question: 'Statement I: The human skull consists of 22 bones.\nStatement II: The human rib cage is formed by 12 pairs of ribs.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly state these standard human skeletal figures.', difficulty: 'medium' },
  { id: 'lm-st-20', type: 'statement', question: 'Statement I: Muscle fatigue occurs due to lactic acid accumulation and depletion of ATP/oxygen.\nStatement II: Muscle fatigue can be relieved partly by rest, allowing lactic acid clearance and energy replenishment.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the cause of muscle fatigue and how rest helps address it.', difficulty: 'medium' },

  // ---- "How many of the following are correct" ----
  { id: 'lm-hm-1', type: 'statement', question: 'How many of the following are examples of movement types found in the human body?\nAmoeboid movement (leucocytes), Ciliary movement (fallopian tube lining), Muscular movement (locomotion), Photosynthetic movement', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Amoeboid, ciliary, and muscular movement are all genuine movement types in the human body; "photosynthetic movement" is not a real category.', difficulty: 'medium' },
  { id: 'lm-hm-2', type: 'statement', question: 'How many of the following bones/bone groups are part of the axial skeleton?\nSkull, Vertebral column, Ribs and sternum, Limb bones', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Skull, vertebral column, and ribs/sternum are axial skeleton components; limb bones belong to the appendicular skeleton.', difficulty: 'medium' },
  { id: 'lm-hm-3', type: 'statement', question: 'How many of the following are examples of freely movable synovial joints?\nShoulder joint, Knee joint, Skull sutures, Hip joint', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Shoulder, knee, and hip are synovial joints; skull sutures are fibrous joints, allowing little to no movement.', difficulty: 'medium' },
  { id: 'lm-hm-4', type: 'statement', question: 'How many of the following are correctly matched (protein – filament type)?\nMyosin – thick filament, Actin – thin filament, Troponin – thick filament, Tropomyosin – thin filament-associated', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Myosin-thick, actin-thin, and tropomyosin-thin filament association are correctly matched; troponin is associated with the thin (actin) filament complex, not the thick filament.', difficulty: 'hard' },
  { id: 'lm-hm-5', type: 'statement', question: 'How many of the following are true regarding the sliding filament theory?\nActin filaments slide over myosin filaments, The A-band length remains constant during contraction, The I-band shortens during contraction, The filaments themselves shorten during contraction', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements correctly describe the sliding filament theory; the filaments themselves do NOT shorten — only their overlap changes.', difficulty: 'medium' },
  { id: 'lm-hm-6', type: 'statement', question: 'How many of the following are steps/components involved in triggering skeletal muscle contraction?\nAcetylcholine release at the neuromuscular junction, Calcium release from the sarcoplasmic reticulum, Calcium binding to troponin, Direct binding of ATP to actin as the trigger step', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three are genuine steps in the contraction-triggering pathway; ATP does not directly trigger contraction by binding actin — its main roles are powering the cross-bridge cycle and detachment.', difficulty: 'hard' },
  { id: 'lm-hm-7', type: 'statement', question: 'How many of the following are disorders related to muscles, bones, or joints?\nMyasthenia gravis, Muscular dystrophy, Osteoporosis, Gout', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four are genuine disorders affecting the muscular/skeletal system.', difficulty: 'easy' },
  { id: 'lm-hm-8', type: 'statement', question: 'How many of the following are correctly matched (disorder – cause)?\nTetany – calcium deficiency, Gout – uric acid crystal accumulation, Osteoporosis – decreased bone mass, Myasthenia gravis – bacterial infection', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three are correctly matched; myasthenia gravis is an autoimmune disorder, not caused by bacterial infection.', difficulty: 'medium' },
  { id: 'lm-hm-9', type: 'statement', question: 'How many of the following are true regarding red and white muscle fibres?\nRed fibres are rich in myoglobin, White fibres rely more on anaerobic glycolysis, Red fibres are better suited for sustained activity, White fibres fatigue more slowly than red fibres', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; white fibres actually fatigue MORE quickly (not more slowly) than red fibres.', difficulty: 'medium' },
  { id: 'lm-hm-10', type: 'statement', question: 'How many of the following joint types are correctly matched to an example?\nBall-and-socket – shoulder joint, Hinge – knee joint, Pivot – atlas-axis joint, Gliding – hip joint', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three matches are correct; the hip joint is actually a ball-and-socket joint, not a gliding joint.', difficulty: 'medium' },
];
